svg.script:
(()=>{'use strict';
  const svg=document.documentElement, button=document.getElementById('motion-toggle');
  if(svg.localName!=='svg'||!button)return;
  let paused=false;
  button.style.display='inline';
  const toggle=()=>{paused=!paused;svg.setAttribute('data-motion',paused?'paused':'on');button.setAttribute('aria-pressed',String(paused));button.setAttribute('aria-label',paused?'继续动画':'暂停动画');document.getElementById('motion-label').textContent=paused?'继续动画 · 点击或空格':'暂停动画 · 点击或空格';};
  button.addEventListener('click',toggle);
  button.addEventListener('keydown',event=>{if(event.key===' '||event.key==='Enter'){event.preventDefault();toggle();}});
})();
